def parse_config(line):
    if not line.startswith("k9://"):
        return {}

    service, rest = line.split("://", 1)
    if not service or not rest:
        return {}

    host, port = rest.split(":", 1)
    if not host or not port:
        return {}

    # Check HOST rules
    labels = host.split(".")
    if not (2 <= len(labels) <= 4):
        return {}
    for label in labels:
        if not (1 <= len(label) <= 8):
            return {}
        if not (label.isalnum() and label[0].islower()):
            return {}

    # PORT must be present
    if not port:
        return {}

    return {"service": service, "host": host, "port": port}
